six.ensure_text:
def ensure_text(s, encoding='utf-8', errors='strict'):
    """Coerce *s* to six.text_type.

    For Python 2:
      - `unicode` -> `unicode`
      - `str` -> `unicode`

    For Python 3:
      - `str` -> `str`
      - `bytes` -> decoded to `str`
    """
    if isinstance(s, binary_type):
        return s.decode(encoding, errors)
    elif isinstance(s, text_type):
        return s
    else:
        raise TypeError("not expecting type '%s'" % type(s))

arrow.locales.get_locale_by_class_name:
def get_locale_by_class_name(name: str) -> 'Locale':
    """Returns an appropriate :class:`Locale <arrow.locales.Locale>`
    corresponding to an locale class name.

    :param name: the name of the locale class.

    """
    locale_cls: Optional[Type[Locale]] = globals().get(name)
    if locale_cls is None:
        raise ValueError(f'Unsupported locale {name!r}.')
    return locale_cls()

dateutil.__init__.__getattr__:
def __getattr__(name):
    import importlib
    if name in __all__:
        return importlib.import_module('.' + name, __name__)
    raise AttributeError('module {!r} has not attribute {!r}'.format(__name__, name))

dateutil.parser.__init__.__deprecated_pr:
def __deprecated_private_func(f):
    from functools import wraps
    import warnings
    msg = '{name} is a private function and may break without warning, it will be moved and or renamed in future versions.'
    msg = msg.format(name=f.__name__)

    @wraps(f)
    def deprecated_func(*args, **kwargs):
        warnings.warn(msg, DeprecationWarning)
        return f(*args, **kwargs)
    return deprecated_func

six.remove_move:
def remove_move(name):
    """Remove item from six.moves."""
    try:
        delattr(_MovedItems, name)
    except AttributeError:
        try:
            del moves.__dict__[name]
        except KeyError:
            raise AttributeError('no such move, %r' % (name, ))

six.reraise:
def reraise(tp, value, tb=None):
    try:
        if value is None:
            value = tp()
        if value.__traceback__ is not tb:
            raise value.with_traceback(tb)
        raise value
    finally:
        value = None
        tb = None
